export async function aiAvailable(){try{const r=await fetch('/api/chat',{signal:AbortSignal.timeout(5000)});return r.ok&&(await r.json()).available===true;}catch{return false;}}
export async function askAI(question,history,language,signal,search=false){const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,history:history.slice(-6).map(t=>({role:t.role,content:t.content.slice(0,1200)})),language,search}),signal});if(!r.ok)throw new Error('AI unavailable');const data=await r.json();if(typeof data.answer!=='string'||!data.answer.trim())throw new Error('Empty answer');return data;}

